/// <summary>
/// Extension of CustInvoiceJour table
/// </summary>
[ExtensionOf(tableStr(CustInvoiceJour))]
final class METCustInvoiceJour_Extension
{
}

Method.Source:
/// <summary>
/// Gets the METCustInvoiceJour
/// </summary>
/// <returns>METCustInvoiceJour buffer</returns>
public METCustInvoiceJour metCustInvoiceJour()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METCustInvoiceJour));
}

    /// <summary>
    /// packs the METCustInvoiceJour
    /// </summary>
    /// <param name = "_metCustInvoiceJour">METCustInvoiceJour to pack</param>
    public void metPackMETCustInvoiceJour(METCustInvoiceJour  _metCustInvoiceJour)
    {
        _metCustInvoiceJour.CustInvoiceJour = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metCustInvoiceJour);
    }

    /// <summary>
    ///    Inserts a table buffer into the database.
    /// </summary>
    public void insert()
    {
        METCustInvoiceJour metCustInvoiceJour;

        next insert();

        metCustInvoiceJour = this.metCustInvoiceJour();
        if (!metCustInvoiceJour.CustInvoiceJour)
        {
            this.metPackMETCustInvoiceJour(metCustInvoiceJour);
        }

        this.SysExtensionSerializerMap::postInsert();
    }

/// <summary>
///    Updates a table buffer into the database.
/// </summary>
public void update()
{
    next update();
    this.SysExtensionSerializerMap::postUpdate();
}

    /// <summary>
    /// Update shipment and load details on journal table
    /// </summary>
    /// <param name = "_shipmentLoadHeader">METSalesOrderShipmentLoadHeader buffer</param>
    public void METUpdateLoadShipmentId(METSalesOrderShipmentLoadHeader     _shipmentLoadHeader)
    {
        ttsbegin;
        
        if (this.RecId)
        {
            this.selectForUpdate(true);
            this.skipDataMethods(true);

            this.METLoadId     = _shipmentLoadHeader.LoadId;
            this.METShipmentId = _shipmentLoadHeader.ShipmentId;
            this.update();
        }

        ttscommit;
    }

    /// <summary>
    /// Method to update load id and shipment id from shipmentLines
    /// </summary>
    /// <param name = "_shipmentLoadHeader">METSalesOrderShipmentLoadHeader reference</param>
    public static void METUpdateLoadShipmentLines(METSalesOrderShipmentLoadHeader       _shipmentLoadHeader)
    {
        METSalesOrderShipmentLoadLines          metSalesOrderShipmentLoadLines;
        SalesLine                               salesLine;
        CustInvoiceTrans                        invoiceTrans;
        CustInvoiceJour                         invoiceJour;

        invoiceJour.skipDataMethods(true);

        update_recordset invoiceJour
            setting METLoadId = _shipmentLoadHeader.LoadId,
                METShipmentId = _shipmentLoadHeader.ShipmentId
            exists join invoiceTrans
                where  invoiceTrans.InvoiceId == invoiceJour.InvoiceId
                    && invoiceTrans.InvoiceDate == invoiceJour.InvoiceDate
                    && invoiceTrans.NumberSequenceGroup == invoiceJour.numberSequenceGroup
                    && invoiceTrans.SalesId == invoiceJour.SalesId
            exists join salesLine
                where salesLine.InventTransId == invoiceTrans.InventTransId
            exists join metSalesOrderShipmentLoadLines
                where metSalesOrderShipmentLoadLines.OrderNum == salesLine.SalesId  &&
                    metSalesOrderShipmentLoadLines.LineNum == salesLine.LineNum     &&
                    metSalesOrderShipmentLoadLines.ShipmentId == _shipmentLoadHeader.ShipmentId;
    }

    /// <summary>
    /// Method to initialise custom fields related to Metcash.
    /// </summary>
    /// <param name = "_custInvoiceTable">CustInvoiceTable buffer</param>
    /// <param name = "_refNum">Reference number, default reference is Customer</param>
    void initFromCustInvoiceTable(CustInvoiceTable _custInvoiceTable, RefNum _refNum)
    {
        next initFromCustInvoiceTable(_custInvoiceTable, _refNum);

        this.METVolumetricTierDeal = _custInvoiceTable.METVolumetricTierDeal;
        this.METTAMRebateTransId = _custInvoiceTable.TAMRebateTransId;
    }

    /// <summary>
    ///     Get report menu item to generate <c>SalesInvoice</c> report.
    /// </summary>
    /// <param name = "_journalPrint">
    ///     The <c>SalesInvoiceJournalPrint</c> class handles the printing of the Sales order invoice.
    /// </param>
    /// <returns>
    ///     Menu item of <c>SalesInvoice</c> report.
    /// </returns>
    protected MenuFunction getSalesInvoiceMenuForPrinting(SalesInvoiceJournalPrint _journalPrint)
    {
        MenuFunction salesInvReportMenu = next getSalesInvoiceMenuForPrinting(_journalPrint);

        if (_journalPrint.parmSalesTable() 
            && METSalesOrderTypes::find(_journalPrint.parmSalesTable().METSalesOrderType).SalesOrderTypeID == METConstants::SalesInvoiceChargeOnly)
        {
            salesInvReportMenu = new MenuFunction(menuitemOutputStr(METSalesChargeOnlyOriginal), MenuItemType::Output);
        }

        return salesInvReportMenu;
    }
